

-- Paths are generated by uploadAttachment. Resolve their period in the server;
-- never authorize uploads from a client-supplied process or document role.
create function public.can_upload_indicator_storage_object(requested_name text)
returns boolean
language plpgsql stable security definer
set search_path = ''
as $$
declare
  parts text[] := string_to_array(requested_name, '/');
  period_key text[];
begin
  if array_length(parts, 1) <> 7
    or parts[1] <> auth.uid()::text
    or parts[2] <> 'attachments'
    or parts[3] <> 'indicators'
    or parts[4] <> 'indicator_result' then
    return false;
  end if;
  period_key := regexp_match(parts[5], '^(IND-[0-9]{3})-([0-9]{4})-(Q[1-4])$');
  if period_key is null then return false; end if;
  return public.indicator_capture_status(
    period_key[1], period_key[2]::integer,
    period_key[3]::public.quarter_code
  ) = 'allowed';
end;
$$;

revoke all on function public.can_upload_indicator_storage_object(text) from public;
grant execute on function public.can_upload_indicator_storage_object(text) to authenticated;

create policy integraq_storage_insert_indicator_evidence
on storage.objects for insert to authenticated
with check (
  bucket_id = 'integraq-private'
  and public.can_upload_indicator_storage_object(name)
);

-- Allow rollback of a failed metadata registration, limited to the uploader's
-- own indicator path and currently authorized capture period.
create policy integraq_storage_delete_indicator_upload
on storage.objects for delete to authenticated
using (
  bucket_id = 'integraq-private'
  and owner_id = auth.uid()::text
  and public.can_upload_indicator_storage_object(name)
  and not exists (
    select 1 from public.file_objects file
    where file.bucket_id = objects.bucket_id and file.object_path = objects.name
  )
);

-- Replacement preserves the old binary and registers a new version. Editors
-- may replace evidence uploaded by another editor of the same indicator.
create policy file_objects_update_indicator_editor
on public.file_objects for update to authenticated
using (
  resource_type = 'indicator_result'
  and module_id = 'indicators'
  and public.can_capture_indicator_evidence(resource_key, process_id)
)
with check (
  resource_type = 'indicator_result'
  and module_id = 'indicators'
  and public.can_capture_indicator_evidence(resource_key, process_id)
);

-- Existing permissive owner policies must not bypass revoked capture rights.
create policy file_objects_indicator_update_capture_guard
on public.file_objects as restrictive for update to authenticated
using (
  resource_type <> 'indicator_result'
  or public.is_administrator()
  or (module_id = 'indicators' and public.can_capture_indicator_evidence(resource_key, process_id))
)
with check (
  resource_type <> 'indicator_result'
  or public.is_administrator()
  or (module_id = 'indicators' and public.can_capture_indicator_evidence(resource_key, process_id))
);

